CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, display_name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equipment (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, capacity INTEGER NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS course_batches (id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, student_count INTEGER NOT NULL, qualification TEXT NOT NULL, status TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS booking_requests (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES course_batches(id), requester_id TEXT NOT NULL REFERENCES users(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, idempotency_key TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(requester_id, idempotency_key));
CREATE TABLE IF NOT EXISTS reservations (id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE REFERENCES booking_requests(id), equipment_id TEXT NOT NULL REFERENCES equipment(id), holder_id TEXT NOT NULL REFERENCES users(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, checked_out_at TEXT, returned_at TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consumables (id TEXT PRIMARY KEY, name TEXT NOT NULL, unit TEXT NOT NULL, quota INTEGER NOT NULL, available INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reservation_consumables (reservation_id TEXT NOT NULL REFERENCES reservations(id), consumable_id TEXT NOT NULL REFERENCES consumables(id), quantity INTEGER NOT NULL, PRIMARY KEY(reservation_id, consumable_id));
CREATE TABLE IF NOT EXISTS maintenance_blocks (id TEXT PRIMARY KEY, equipment_id TEXT NOT NULL REFERENCES equipment(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, reason TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY, reservation_id TEXT REFERENCES reservations(id), equipment_id TEXT REFERENCES equipment(id), reported_by TEXT NOT NULL REFERENCES users(id), severity TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, outcome TEXT NOT NULL, request_id TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_records (key TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), request_hash TEXT NOT NULL, response_code INTEGER NOT NULL, response_body TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reservations_equipment_time ON reservations(equipment_id, starts_at, ends_at, status);
CREATE INDEX IF NOT EXISTS idx_blocks_equipment_time ON maintenance_blocks(equipment_id, starts_at, ends_at, status);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_events(entity_type, entity_id, created_at);
